mapper.select:
select *
from ems_alarm_event
where tenant_id = #{tenantId}
  and station_id = #{stationId}
  and alarm_code = #{alarmCode}
  and alarm_status = 'ACTIVE'


        and device_id = #{deviceId}


        and device_id is null


order by id desc
limit 1

mapper.delete:
delete from ems_alarm_event
where tenant_id = #{tenantId}
  and alarm_status in ('ACKED', 'CLEARED')
  and coalesce(clear_time, ack_time, last_time, first_time) < #{beforeTime}
